{
  "technical_and_design_decisions": [
    "Implement Solo orderer as a new package implementing the existing Orderer interface, using an in-memory ledger and a buffered Go channel with a single goroutine creating blocks.",
    "Support deliver service with SeekOldest, SeekNewest, and Seek specific block number using the in-RAM ledger to allow disconnect/reconnect.",
    "Add friendly chaincode name as optional metadata stored in the Lifecycle System Chaincode (LSCC) and indexed per channel.",
    "Extend LSCC to store and retrieve deployment policies as part of chaincode instantiation and upgrade.",
    "Implement a per-peer in-memory LRU state cache that intercepts state reads during endorsement to accelerate rw-set construction, with invalidation on block commit.",
    "Extract CLI into a separate Go module/binary that communicates with peer and orderer via gRPC, removing dependency on peer internals and RocksDB.",
    "Use Go cross-compilation and platform-specific packaging scripts for CLI distribution on Mac, Windows, and Linux.",
    "Mirror the Gerrit repository to GitHub via a CI job and update README to point to GitHub for browsing.",
    "Publish and link Fabric documentation on the hyperledger.org docs portal and provide local upgrade flow docs in the repo."
  ],
  "assumptions": [
    "Existing Hyperledger Fabric codebase, build tooling, and test infrastructure are available and familiar to the developer.",
    "Solo orderer does not require persistence across restarts; an in-RAM ledger is sufficient for development and test.",
    "State cache is process-local and not shared across peers; consistency is maintained via commit-time invalidation.",
    "Deployment policies reuse existing policy primitives if available; otherwise a minimal signature policy format is defined.",
    "CLI extraction targets the most commonly used peer subcommands and does not need to replicate all deprecated admin commands in this increment.",
    "Documentation tasks cover writing or updating Markdown/static site content; no full website redesign is required.",
    "Effort estimates reflect personal development work only and exclude external code review cycles and elapsed time for upstream merge.",
    "All estimates are expressed in work-hours for a single experienced Go developer."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Set up GitHub mirror (U5)",
      "activity_description": "Configure CI sync from Gerrit to GitHub, verify repository is browsable, update README links.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "Design Solo orderer (U4)",
      "activity_description": "Define interfaces, batching parameters, in-RAM ledger structure, and seek protocol for the Solo ordering service.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Solo ordering path (U4)",
      "activity_description": "Implement buffered channel, single consumer goroutine, and batch/block creation logic.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement Solo deliver path (U4)",
      "activity_description": "Implement in-RAM ledger, block storage, and deliver service with seek (oldest/newest/specific) and reconnect support.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A5",
      "activity_name": "Integrate and test Solo orderer (U4)",
      "activity_description": "Wire Solo orderer into orderer factory, add sample config, write unit and integration tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "Design friendly chaincode name (U1)",
      "activity_description": "Design metadata schema, API changes, and LSCC storage approach for friendly chaincode names.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement friendly chaincode name (U1)",
      "activity_description": "Add friendly name field to lifecycle system chaincode, peer APIs, and CLI/SDK references.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A8",
      "activity_name": "Test friendly chaincode name (U1)",
      "activity_description": "Write unit and integration tests for registration, lookup, and debugging by friendly name.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "Design LSCC deployment policies (U2)",
      "activity_description": "Design policy data model, LSCC methods for managing deployment policies, and enforcement points.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A10",
      "activity_name": "Implement LSCC deployment policies (U2)",
      "activity_description": "Implement storage, retrieval, and validation of deployment policies in the lifecycle system chaincode.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A11",
      "activity_name": "Integrate deployment policy enforcement (U2)",
      "activity_description": "Invoke policy checks during endorsement and commit paths in the peer node.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A12",
      "activity_name": "Test deployment policies (U2)",
      "activity_description": "Write unit and scenario tests for policy management and enforcement.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A13",
      "activity_name": "Design state cache (U6)",
      "activity_description": "Design LRU cache interface and integration with state database and rw-set builder.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A14",
      "activity_name": "Implement state cache (U6)",
      "activity_description": "Implement cache for state reads, serve from cache, and track keys to help build rw-set quickly.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A15",
      "activity_name": "Integrate and test state cache (U6)",
      "activity_description": "Add invalidation on block commit, and write correctness and performance tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A16",
      "activity_name": "Design standalone CLI (U8)",
      "activity_description": "Design separate module structure, gRPC client stubs, and command mapping for extracted CLI.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A17",
      "activity_name": "Refactor peer commands into CLI (U8)",
      "activity_description": "Extract peer command code into standalone binary, remove RocksDB and peer internal dependencies, implement commands.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A18",
      "activity_name": "Build and package CLI (U8)",
      "activity_description": "Cross-compile for Mac, Windows, Linux, create installers, and run smoke tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A19",
      "activity_name": "Write upgrade flows documentation (U3)",
      "activity_description": "Author step-by-step upgrade flow guides for chaincode and network upgrades.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A20",
      "activity_name": "Publish and index documentation (U7)",
      "activity_description": "Submit links and improve documentation landing page so Fabric docs are easily found at hyperledger.org.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A21",
      "activity_name": "Overall integration and regression",
      "activity_description": "Perform full build, cross-feature regression testing, and fix integration issues for the complete increment.",
      "most_likely_effort": 32
    }
  ],
  "reported_total": {
    "most_likely_effort": 456
  }
}

